CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `Dynamic_Data_Nomina` AS
with `base_data` as (select `ds`.`IdServicio` AS `IdServicio`,`ds`.`IdRecibo` AS `IdRecibo`,`dr`.`Operación` AS `Operacion`,`ds`.`Estado` AS `Estado`,`ds`.`Usuario` AS `Usuario`,`ds`.`Usuario` AS `Usuario_Texto`,`ds`.`Area` AS `Area`,`ca`.`AREA` AS `Area_Texto`,`ds`.`Fecha` AS `Fecha`,`ds`.`Transportadora` AS `Transportadora`,`ds`.`Proveedor` AS `Proveedor`,`mprov`.`Proveedor` AS `Proveedor_Maestro`,`ds`.`Proveedor Texto` AS `Proveedor_Texto`,`ds`.`Actividad` AS `Actividad`,`cact`.`Actividad` AS `Actividad_Texto`,`ds`.`Vehiculo` AS `Vehiculo`,`ds`.`Remolque` AS `Remolque`,`ds`.`PL1` AS `PL1`,`mpl`.`Placa` AS `PL2`,`ds`.`Unidad` AS `Unidad`,`ds`.`Cantidad` AS `Cantidad`,`ds`.`Valor Unitario` AS `Valor_Unitario`,`ds`.`Origen` AS `Origen`,`ds`.`Destino` AS `Destino`,`ds`.`Manifiesto` AS `Manifiesto`,`ds`.`Foto Documento` AS `Foto_Documento`,`ds`.`Etapa` AS `Etapa`,`ds`.`Muelle` AS `Muelle`,`ds`.`Hora Inicio` AS `Hora_Inicio`,`ds`.`Hora Final` AS `Hora_Final`,`ds`.`Total Hora` AS `Total_Hora`,`ds`.`Grupo Dtjo` AS `Grupo_Dtjo`,`ds`.`Auxiliares` AS `Auxiliares`,`ds`.`Notas` AS `Notas`,`ds`.`Foto Evidencia` AS `Foto_Evidencia`,`ds`.`Forma De Pago` AS `Forma_De_Pago`,`ds`.`Foto Transferencia` AS `Foto_Transferencia`,`ds`.`Fecha Transferencia` AS `Fecha_Transferencia`,`ds`.`Observaciones` AS `Observaciones`,`ds`.`Firma_Recibido` AS `Firma_Recibido`,`ds`.`Edición` AS `Edición`,`dr`.`Nit` AS `Nit_Cliente`,`mc`.`Razón social` AS `Nombres`,`dr`.`Telefono` AS `Telefono`,`dr`.`Email` AS `Email`,`dr`.`Cliente a Facturar` AS `Cliente_a_Facturar`,`ccs`.`Categoria` AS `Categoria_Texto`,`dr`.`Retefuente` AS `ReteFuente`,`dr`.`ReteIVA` AS `ReteIVA`,`dr`.`ReteICA` AS `ReteICA`,`imp`.`iva_porcentaje` AS `iva_porcentaje`,`imp`.`retefuente_porcentaje` AS `retefuente_porcentaje`,`imp`.`reteiva_porcentaje` AS `reteiva_porcentaje`,coalesce(`rica`.`Porcentaje`,`imp`.`reteica_porcentaje`) AS `reteica_porcentaje`,`dr`.`Consecutivo Recibo` AS `Consecutivo_Recibo`,`mo`.`CODIGO CO SIESA` AS `Codigo_SIESA`,`mo`.`REGIONAL` AS `REGIONAL`,`mt`.`Transportadora` AS `Transportadora_Texto` from (((((((((((`Desplegables`.`Dynamic_Servicios` `ds` left join `Desplegables`.`Dynamic_Recibos` `dr` on((`ds`.`IdRecibo` = `dr`.`IdRecibo`))) left join `Desplegables`.`Maestro_Operaciones` `mo` on((`dr`.`Operación` = `mo`.`OPERACIÓN`))) left join `Desplegables`.`Maestro_Clientes` `mc` on((`dr`.`Nit` = `mc`.`Código`))) left join `Desplegables`.`Config_Categoria_Serv` `ccs` on((`dr`.`Categoria` = `ccs`.`Id`))) left join `Desplegables`.`Config_Area` `ca` on((`ds`.`Area` = `ca`.`ID`))) left join `Desplegables`.`Maestro_Transportadora` `mt` on((`ds`.`Transportadora` = `mt`.`ID`))) left join `Desplegables`.`Maestro_Proveedor` `mprov` on((`ds`.`Proveedor` = `mprov`.`ID`))) left join `Desplegables`.`Config_Actividad` `cact` on((`ds`.`Actividad` = `cact`.`ID`))) left join `Desplegables`.`Maestro_Placas` `mpl` on((`ds`.`PL1` = `mpl`.`ID`))) left join (select max((case when (`Desplegables`.`Config_Impuestos`.`Concepto` = 'IVA') then `Desplegables`.`Config_Impuestos`.`Porcentaje` end)) AS `iva_porcentaje`,max((case when (`Desplegables`.`Config_Impuestos`.`Concepto` = 'ReteFuente') then `Desplegables`.`Config_Impuestos`.`Porcentaje` end)) AS `retefuente_porcentaje`,max((case when (`Desplegables`.`Config_Impuestos`.`Concepto` = 'ReteIVA') then `Desplegables`.`Config_Impuestos`.`Porcentaje` end)) AS `reteiva_porcentaje`,max((case when (`Desplegables`.`Config_Impuestos`.`Concepto` = 'ReteICA') then `Desplegables`.`Config_Impuestos`.`Porcentaje` end)) AS `reteica_porcentaje` from `Desplegables`.`Config_Impuestos`) `imp` on((1 = 1))) left join (select `Desplegables`.`Config_Impuestos`.`Operación` AS `Operación`,max(`Desplegables`.`Config_Impuestos`.`Porcentaje`) AS `Porcentaje` from `Desplegables`.`Config_Impuestos` where (`Desplegables`.`Config_Impuestos`.`Concepto` like '%ReteICA%') group by `Desplegables`.`Config_Impuestos`.`Operación`) `rica` on((`dr`.`Operación` = `rica`.`Operación`))) where (`ds`.`Hora Inicio` >= '2026-01-01')), `destajo_data` as (select `cd`.`Operación` AS `Operacion`,`cd`.`Valor Dtjo` AS `Valor_Dtjo`,`cd`.`Destajo` AS `Destajo`,`cd`.`Unidad` AS `Unidad`,row_number() OVER (PARTITION BY `cd`.`Operación` ORDER BY `cd`.`Valor Dtjo` desc )  AS `rn` from `Desplegables`.`Config_Destajo` `cd`) select concat(month(`b`.`Hora_Inicio`),'. ',(case month(`b`.`Hora_Inicio`) when 1 then 'Enero' when 2 then 'Febrero' when 3 then 'Marzo' when 4 then 'Abril' when 5 then 'Mayo' when 6 then 'Junio' when 7 then 'Julio' when 8 then 'Agosto' when 9 then 'Septiembre' when 10 then 'Octubre' when 11 then 'Noviembre' when 12 then 'Diciembre' end),if((dayofmonth(`b`.`Hora_Inicio`) > 15),' Q2',' Q1')) AS `QUINCENA`,coalesce(`b`.`REGIONAL`,'N/A') AS `REGIONAL`,`b`.`Operacion` AS `OPERACIÓN`,`b`.`Area_Texto` AS `AREA`,`b`.`Hora_Inicio` AS `FECHA`,(case when (`b`.`Forma_De_Pago` = 7) then 0 else `b`.`Forma_De_Pago` end) AS `FORMA DE PAGO`,`b`.`Consecutivo_Recibo` AS `CONSECUTIVO RECIBO`,`b`.`Codigo_SIESA` AS `PREFIJO RECIBO`,`b`.`Cliente_a_Facturar` AS `CLIENTE A FACTURAR`,`b`.`IdServicio` AS `# RECIBO`,`b`.`Categoria_Texto` AS `# FACTURA`,upper(coalesce(`b`.`Transportadora_Texto`,`b`.`Transportadora`)) AS `TRANSPORTADORA`,upper(coalesce(`b`.`Proveedor_Maestro`,`b`.`Proveedor`)) AS `PROVEEDOR`,`b`.`Origen` AS `CODIGO DEPENDENCIA`,`b`.`Destino` AS `DEPENDENCIA`,`b`.`Vehiculo` AS `VEHICULO`,`b`.`PL2` AS `PLACA`,`b`.`Actividad_Texto` AS `ACTIVIDAD`,`b`.`Manifiesto` AS `MANIFIESTO`,`b`.`Remolque` AS `REMOLQUE`,`b`.`Unidad` AS `UNIDAD`,`b`.`Cantidad` AS `CANT`,`b`.`Valor_Unitario` AS `V.UNIT`,(case when (`b`.`Forma_De_Pago` = 1) then round((`b`.`Cantidad` * `b`.`Valor_Unitario`),2) end) AS `VALOR EFECTIVO`,(case when (`b`.`Forma_De_Pago` = 2) then round((`b`.`Cantidad` * `b`.`Valor_Unitario`),2) end) AS `VALOR TRANSFERENCIA`,(case when (`b`.`Forma_De_Pago` = 3) then round((`b`.`Cantidad` * `b`.`Valor_Unitario`),2) end) AS `VALOR CREDITO`,(case when (`b`.`Forma_De_Pago` in (1,2,3)) then round(((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `b`.`iva_porcentaje`),2) end) AS `IVA`,(case when (`b`.`Forma_De_Pago` in (1,2,3)) then round((((case when (`b`.`ReteFuente` = 'V') then ((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `b`.`retefuente_porcentaje`) else 0 end) + (case when (`b`.`ReteIVA` = 'V') then (((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `b`.`iva_porcentaje`) * `b`.`reteiva_porcentaje`) else 0 end)) + (case when (`b`.`ReteICA` = 'V') then ((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `b`.`reteica_porcentaje`) else 0 end)),2) end) AS `RETENCION`,(case when (`b`.`Forma_De_Pago` in (1,2,3)) then round((((((`b`.`Cantidad` * `b`.`Valor_Unitario`) + ((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `b`.`iva_porcentaje`)) - (case when (`b`.`ReteFuente` = 'V') then ((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `b`.`retefuente_porcentaje`) else 0 end)) - (case when (`b`.`ReteIVA` = 'V') then (((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `b`.`iva_porcentaje`) * `b`.`reteiva_porcentaje`) else 0 end)) - (case when (`b`.`ReteICA` = 'V') then ((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `b`.`reteica_porcentaje`) else 0 end)),2) end) AS `TOTAL`,(case when (`b`.`Forma_De_Pago` in (1,2,3)) then round((`b`.`Cantidad` * `b`.`Valor_Unitario`),2) end) AS `V.NOM`,(case when (`b`.`Forma_De_Pago` in (1,2,3)) then (case when ((`d`.`Valor_Dtjo` > 0) and (`d`.`Unidad` = `b`.`Unidad`)) then round((`b`.`Cantidad` * `d`.`Valor_Dtjo`),2) else round(((`b`.`Cantidad` * `b`.`Valor_Unitario`) * `d`.`Destajo`),2) end) end) AS `DTJO`,`b`.`Grupo_Dtjo` AS `# TRAB`,`b`.`Auxiliares` AS `TRABAJADOR`,(case when ((`b`.`Area_Texto` like '%MP%') or (`b`.`Operacion` like '%D1 Cúcuta%') or (`b`.`Operacion` like '%Diana Cota%')) then `b`.`Etapa` else `b`.`Area_Texto` end) AS `AREA2`,`b`.`Muelle` AS `MUELLE`,`b`.`Hora_Inicio` AS `HORA INICIO`,`b`.`Hora_Final` AS `HORA FINAL`,time_format(`b`.`Total_Hora`,'%H:%i:%s') AS `TOTAL HORA`,concat((case when (lower(`b`.`Estado`) like '%reen%') then 'OK' when (lower(`b`.`Estado`) like '%ellow%') then 'NO' else 'X' end),' - ',coalesce(date_format(`b`.`Hora_Inicio`,'%H:%i'),'Sin hora'),' - ',coalesce(`b`.`Usuario`,'Sin usuario'),' - ',coalesce(`b`.`Observaciones`,'Sin observaciones'),' - ',coalesce(`b`.`Notas`,'Sin notas'),'%',coalesce(`b`.`Fecha_Transferencia`,'Sin fecha')) AS `OBSERVACIONES`,`b`.`Nit_Cliente` AS `NIT`,`b`.`Nombres` AS `NOMBRES`,`b`.`Telefono` AS `TELEFONO`,`b`.`Email` AS `EMAIL` from (`base_data` `b` left join `destajo_data` `d` on(((`b`.`Operacion` = `d`.`Operacion`) and (`d`.`rn` = 1))));
